// logit_rf.v
// ------------------------------------------------------------
// Tiny 10-entry x 16-bit register file that bridges fc3 to
// argmax_wrapper.
//
// fc3 produces 10 INT16 logits; the 8-bit feature_buffer cannot
// store these without truncation, so we use a dedicated
// register file. argmax_wrapper reads from it combinationally.
//
// Interface:
//   Write port (1 entry per cycle when write_en=1):
//     write_addr  [3:0]   : 0..9
//     write_data  [15:0]  : INT16 logit value
//     write_en
//   Read port (combinational, no enable):
//     read_addr   [3:0]   : 0..9
//     read_data   [15:0]  : current value at read_addr
//
// Write is sync (posedge clk). Read is combinational, so the
// argmax_wrapper sees stable data on the same cycle it issues
// read_addr.
//
// Reset clears all entries to 0.
// ============================================================

`timescale 1ns / 1ps

module logit_rf #(
    parameter integer LOGIT_W = 16,
    parameter integer NUM     = 10
)(
    input  wire                       clk,
    input  wire                       rst_n,

    // Write port
    input  wire [3:0]                 write_addr,
    input  wire signed [LOGIT_W-1:0]  write_data,
    input  wire                       write_en,

    // Read port (combinational)
    input  wire [3:0]                 read_addr,
    output wire signed [LOGIT_W-1:0]  read_data
);

    reg signed [LOGIT_W-1:0] mem [0:NUM-1];

    integer i;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < NUM; i = i + 1) begin
                mem[i] <= 0;
            end
        end else if (write_en && write_addr < NUM) begin
            mem[write_addr] <= write_data;
        end
    end

    assign read_data = (read_addr < NUM) ? mem[read_addr] : {LOGIT_W{1'b0}};

endmodule
